content.css:
.incident-visual {
  font-family: "Segoe UI", sans-serif;
  height: 100%;
  overflow: hidden;
}
.incident-visual .toolbar {
  display: flex;
  gap: 4px;
  padding: 4px;
  height: 32px;
  box-sizing: border-box;
}
.incident-visual .toolbar button {
  border: 1px solid #c8c8c8;
  background: #fff;
  padding: 2px 10px;
  border-radius: 3px;
  cursor: pointer;
}
.incident-visual .toolbar button.active {
  background: #118dff;
  border-color: #118dff;
  color: #fff;
}
.incident-visual .bar {
  cursor: pointer;
}
.incident-visual text {
  fill: #444;
  font-size: 10px;
}
